function learningMarkdown(text){
 const escaped=esc(text||'');const inline=s=>s.replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
 return escaped.split(/\n\s*\n/).map(block=>{
  if(/^#{1,4}\s/.test(block))return block.split('\n').map(line=>/^#{1,4}\s/.test(line)?'<h3>'+inline(line.replace(/^#{1,4}\s+/,''))+'</h3>':'<p>'+inline(line)+'</p>').join('');
  if(block.split('\n').every(line=>/^\s*(?:[-*•]|\d+[.)、])\s/.test(line)))return '<ul>'+block.split('\n').map(line=>'<li>'+inline(line.replace(/^\s*(?:[-*•]|\d+[.)、])\s+/,''))+'</li>').join('')+'</ul>';
  return '<p>'+inline(block).replace(/\n/g,'<br>')+'</p>';
 }).join('');
}
function learningCitations(citations){if(!citations?.length)return '';return '<details class="learningSources"><summary>课件出处 · '+citations.length+'</summary>'+citations.map(c=>`<blockquote><strong>[${esc(c.ref)}] ${esc(c.filename)}</strong><small>Week ${Number(c.week)||1} · 文字段 ${Number(c.section)||1}</small><p>${esc(c.quote)}</p></blockquote>`).join('')+'</details>'}
function learningCoverage(c){if(!c)return '';const weeks=a=>a?.length?a.map(w=>'Week '+Number(w)).join('、'):'暂无';const missing=(c.uploaded_weeks||[]).filter(w=>!c.supported_weeks?.includes(w));return `<details class="learningSources learningCoverage" ontoggle="if(this.open)this.scrollIntoView({block:'nearest'})"><summary>依据与范围 · ${Number(c.used_files)||0} 份课件</summary><p>已上传 ${Number(c.uploaded_files)||0} 份；本次选取 ${Number(c.inspected_files)||0} 份核对，结论引用其中 ${Number(c.used_files)||0} 份。</p><p>回答依据涉及：${esc(weeks(c.supported_weeks))}。</p>${c.sampled?'<p>课程概览按各文件的代表片段整理，不表示逐页审阅或覆盖未上传的教学内容。</p>':''}${c.mode==='overview'&&missing.length?`<p>本次未形成有依据概述的周次：${esc(weeks(missing))}。可指定该 Week 继续问。</p>`:''}${c.mode==='overview'&&c.omitted_files?.length?'<p>本次未选取：'+c.omitted_files.map(f=>esc(f.filename)).join('、')+'。</p>':''}</details>`}
