function showLearningSample(){
 courseDialog('学习示例 · 不计入掌握进度',`<div class="sampleLesson"><span class="welcomeEyebrow">体验一次：讲解 → 追问 → 练习</span><h3>研究问题和假设，有什么区别？</h3><p><strong>Research question · 研究问题</strong><br>先问：我们想研究什么？</p><p><strong>Hypothesis · 假设</strong><br>再提出：我们预测会发生什么，并且能用数据检验。</p><p class="workspaceHint">辅助例子：研究问题问“不同复习方法与记忆效果有什么关系？”；假设预测“提取练习组比重读组记住更多概念”。这是预设体验示例，不是你的课程原文，也不是实时 AI 回答。</p><details><summary>用更简单的话说</summary><p>研究问题是“我想知道什么”，假设是“我猜结果是什么，而且可以检验”。</p></details><details><summary>试一题，看看是否理解</summary><p>“增加复习间隔会提高一周后的回忆成绩。”这更像研究问题还是假设？</p><button class="secondary" onclick="document.getElementById('sampleFeedback').textContent='这是对结果的具体预测，因此属于假设。研究问题通常先提出要探究的关系。'">假设</button><button class="newChat" onclick="document.getElementById('sampleFeedback').textContent='再看一句：它预测了会发生什么，而不仅是在提问，所以更接近假设。'">研究问题</button><p id="sampleFeedback" role="status"></p></details></div>`);
}

function renderStudyPicker(id,label,value,options,onChoose){
 studyPickerModels.set(id,{options,onChoose});const selected=options.find(o=>String(o.value)===String(value));
 return `<input type="hidden" id="${id}" value="${esc(value)}"><details class="studyPicker" id="${id}Menu"><summary aria-label="${esc(label)}"><span class="pickerCaption">${esc(label)}</span><strong>${esc(selected?.label||'请选择')}</strong><span class="pickerChevron">⌄</span></summary><div class="studyPickerMenu">${options.length>7?`<input type="search" aria-label="搜索${esc(label)}" placeholder="搜索…" oninput="filterStudyPicker('${id}',this.value)">`:''}<div class="pickerOptions">${options.map((o,i)=>`<button type="button" onclick="pickStudyValue('${id}',${i})" ${String(o.value)===String(value)?'aria-current="true"':''}>${esc(o.label)}${String(o.value)===String(value)?'<span>✓</span>':''}</button>`).join('')}</div><p class="pickerNoResults" role="status" hidden>没有匹配结果，试试其他关键词。</p></div></details>`;
}
function pickStudyValue(id,index){const model=studyPickerModels.get(id),option=model?.options[index];if(!option)return;const menu=document.getElementById(id+'Menu'),input=document.getElementById(id);if(input)input.value=String(option.value);if(menu){menu.open=false;const label=menu.querySelector('summary strong');if(label)label.textContent=option.label;menu.querySelectorAll('.pickerOptions button').forEach((button,i)=>{button.removeAttribute('aria-current');button.querySelector('span')?.remove();if(i===index){button.setAttribute('aria-current','true');const mark=document.createElement('span');mark.textContent='✓';button.append(mark)}})}model.onChoose(option.value)}
function filterStudyPicker(id,text){const el=document.getElementById(id+'Menu');if(!el)return;let visible=0;el.querySelectorAll('.pickerOptions button').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(text.trim().toLowerCase());if(!b.hidden)visible++});const empty=el.querySelector('.pickerNoResults');if(empty)empty.hidden=visible>0}
