function readingSources(){const course=workspaceScope();return (learningState.sources||[]).filter(s=>course&&s.course_id===course&&(!readingPane.week||Number(s.week)===Number(readingPane.week)))}
function renderReadingShell(){
 return `<aside class="readingPane" aria-label="课件阅读区"><header><strong>课件</strong><button class="readerScopeShortcut" onclick="chooseNotebookCourse()" aria-label="切换课件课程和周次">切换课程 / 周次 ⌄</button></header><div id="readingControls" class="readingControls"></div><div class="splitMobileTabs"><button onclick="switchReadingMobile('reader')">课件</button><button onclick="switchReadingMobile('notebook')">笔记本 →</button></div><div id="readingScroll" class="readingScroll">${readingPane.html||'<p class="readerEmpty">正在读取材料…</p>'}</div><footer><button onclick="quoteReadingSelection()">引用选中文字</button><span id="readingStatus" role="status" data-study-sync>${typeof studySyncMessage!=='undefined'?esc(studySyncMessage):''}</span></footer></aside>`;
}
function renderReadingEmptyState(tab='source'){
 const course=courseRows.find(c=>c.id===workspaceScope()),scope=(course?.code||course?.name||'当前课程')+(readingPane.week?' · Week '+Number(readingPane.week):'');
 return `<section class="readerEmpty readerEmptyState"><span class="readerEmptyIcon">${lexIcon(tab==='source'?'file':'book')}</span><small>${esc(scope)}</small><h3>${tab==='source'?'这一周还没有课件':'还没有学习笔记'}</h3><p>${tab==='source'?'可以添加本周课件，也可以先记下课堂内容。其他周的资料不会出现在这里。':'写下自己的理解，或把莱克的讲解存为笔记。'}</p><div class="readerEmptyActions">${tab==='source'?'<button class="secondary" onclick="showCourseWorkspace(\'materials\',workspaceScope())">添加或管理课件</button>':''}<button class="newChat" onclick="switchReadingMobile('notebook')">去记笔记 →</button></div></section>`;
}
function renderNotebookShell(){return `<section class="notebookPanel" aria-label="笔记本"><div class="notebookChrome"><header class="notebookHeader"><div><strong>笔记本</strong><small>${esc(courseRows.find(c=>c.id===workspaceScope())?.code||'当前课程')}${readingPane.week?' · Week '+Number(readingPane.week):''}</small></div><button class="newChat" onclick="toggleReadingPane()" aria-label="退出笔记分屏">退出分屏</button></header><div class="splitMobileTabs"><button onclick="switchReadingMobile('reader')">课件</button><button onclick="switchReadingMobile('notebook')">笔记本</button></div><div class="studySyncStatus" data-study-sync role="status">${typeof studySyncMessage!=='undefined'?esc(studySyncMessage):''}</div><div id="notebookRangeControls" class="notebookRangeControls"></div><div class="notebookTools"><div id="notebookPicker"></div><button class="newChat" onclick="newNotebookNote()">＋ 新笔记</button></div></div><button id="mobileNoteControls" class="mobileNoteControls" aria-expanded="true" onclick="setMobileNoteControls(document.body.classList.contains('mobileNoteFocused'))">收起工具</button><div id="notebookMount"><div id="workspaceContent">正在打开笔记…</div></div></section>`}
function syncNotebookAI(){const panel=document.querySelector('.lexFloatingPanel'),orb=document.querySelector('.lexOrb');if(panel)panel.hidden=!readingPane.aiOpen;if(orb){orb.setAttribute('aria-expanded',String(Boolean(readingPane.aiOpen)));orb.setAttribute('aria-label',readingPane.aiOpen?'收起莱克':'唤醒莱克')}}
function toggleNotebookAI(open){readingPane.aiOpen=typeof open==='boolean'?open:!readingPane.aiOpen;const panel=document.querySelector('.lexFloatingPanel');if(!readingPane.aiOpen&&panel?.contains?.(document.activeElement))document.activeElement?.blur?.();syncNotebookAI();if(readingPane.aiOpen)document.getElementById('materialPrompt')?.focus({preventScroll:true});else document.querySelector('.lexOrb')?.focus?.({preventScroll:true})}

function setReadingTab(tab){readingPane.tab=tab;readingPane.id='';readingPane.key='';readingPane.html='';readingPane.scroll=0;renderStudyAssistant()}
function chooseReadingItem(id){if(typeof saveReadingResume==='function')saveReadingResume();readingPane.id=id;readingPane.key='';readingPane.html='';readingPane.scroll=0;loadReadingPane()}
function jumpReadingPage(page){readingPane.page=Number(page);const area=document.getElementById('readingScroll'),target=document.getElementById('lecturePage'+readingPane.page);if(area&&target){area.scrollTop+=target.getBoundingClientRect().top-area.getBoundingClientRect().top;readingPane.scroll=area.scrollTop}}
function toggleReadingPdf(){readingPane.pdf=!readingPane.pdf;readingPane.key='';readingPane.html='';loadReadingPane()}
async function loadReadingPane(){
 const content=document.getElementById('readingScroll'),controls=document.getElementById('readingControls');if(!content||!controls)return;
 const course=workspaceScope(),uid=session?.user.id;if(!course){content.innerHTML='<p class="readerEmpty">先选择一门课程，再并排阅读对应的课件或笔记。</p>';return}
 const serial=++readingPane.serial,tab=readingPane.tab;
 try{
  const rows=tab==='source'?readingSources():await sb('user_course_notes?select=id,title,body,updated_at&course_id=eq.'+course+'&order=updated_at.desc');
  if(serial!==readingPane.serial||session?.user.id!==uid||!readingPane.open)return;
  if(!rows.length){content.innerHTML=renderReadingEmptyState(tab);controls.innerHTML='';return}
  if(!rows.some(r=>r.id===readingPane.id)){if(readingPane.id){readingPane.scroll=0;readingPane.page=Array.isArray(window.SINQ_LECTURE_PAGES)?window.SINQ_LECTURE_PAGES[0]:1}readingPane.id=rows[0].id;}
  let row=rows.find(r=>r.id===readingPane.id);if(tab==='source'&&typeof renderOriginalPdf==='function'){try{const [original]=await sb('user_learning_sources?id=eq.'+row.id+'&select=original_path,original_pages,original_bytes');if(serial!==readingPane.serial||session?.user.id!==uid||!readingPane.open)return;row={...row,...original}}catch{}}
  const uploadedPdf=tab==='source'&&Boolean(row.original_path),pdf=uploadedPdf||tab==='source'&&Boolean(window.SINQ_LECTURE_URL)&&row.filename.startsWith('W1_Canvas');
  controls.innerHTML=renderStudyPicker('readingItem',tab==='source'?'阅读课件':'阅读笔记',row.id,rows.map(r=>({value:r.id,label:tab==='source'?r.filename:r.title})),chooseReadingItem)+(pdf?`<button class="readerViewToggle" onclick="toggleReadingPdf()">${readingPane.pdf?'切换提取文字':'打开原始 PDF'}</button>`:'');
  if(!uploadedPdf&&pdf&&readingPane.pdf&&Array.isArray(window.SINQ_LECTURE_PAGES))controls.innerHTML+=renderStudyPicker('readingPage','课件页码',String(readingPane.page),window.SINQ_LECTURE_PAGES.map(page=>({value:String(page),label:'第 '+Number(page)+' 页'})),jumpReadingPage);
  if(tab==='source'&&!pdf&&typeof originalPdfAttachControl==='function')controls.insertAdjacentHTML('beforeend',originalPdfAttachControl());
  if(uploadedPdf&&readingPane.pdf){content.innerHTML='<p class="readerEmpty">正在读取原始PDF…</p>';await renderOriginalPdf(row,content,controls);return}
  const key=[uid,course,tab,row.id,row.updated_at||'',pdf&&readingPane.pdf?'pdf':'text'].join(':');
  if(readingPane.key===key&&readingPane.html){if(content.dataset.loadedKey!==key){content.innerHTML=readingPane.html;content.dataset.loadedKey=key;content.scrollTop=readingPane.scroll;if(typeof applyReadingResumePosition==='function')applyReadingResumePosition(content)}return}
  content.innerHTML='<p class="readerEmpty">正在读取…</p>';
  let html;
  if(pdf&&readingPane.pdf&&Array.isArray(window.SINQ_LECTURE_PAGES))html='<article class="readerSlides">'+window.SINQ_LECTURE_PAGES.map(page=>'<figure id="lecturePage'+Number(page)+'"><figcaption>课件第 '+Number(page)+' 页</figcaption><img width="1400" height="788" loading="lazy" src="/__lecture-pages/'+Number(page)+'.jpg" alt="COM5101 Week 1 第 '+Number(page)+' 页"></figure>').join('')+'</article>';
  else if(pdf&&readingPane.pdf)html=`<iframe class="lecturePdf" title="Week 1 原始课件 PDF" src="${esc(window.SINQ_LECTURE_URL)}#page=23&view=FitH"></iframe>`;
  else if(tab==='notes')html='<article class="readerDocument"><h2>'+esc(row.title)+'</h2>'+learningMarkdown(row.body)+'</article>';
  else{const chunks=await sb('user_learning_chunks?source_id=eq.'+encodeURIComponent(row.id)+'&select=ordinal,content&order=ordinal.asc');html='<article class="readerDocument"><h2>'+esc(row.filename)+'</h2><p class="readerMeta">Week '+Number(row.week)+' · 提取文字，图表可能不完整</p>'+chunks.map(r=>'<p>'+esc(r.content)+'</p>').join('')+'</article>'}
  if(serial!==readingPane.serial||session?.user.id!==uid||!readingPane.open)return;
  readingPane.key=key;readingPane.html=html;content.innerHTML=html;content.dataset.loadedKey=key;content.onscroll=trackReadingScroll;content.scrollTop=readingPane.scroll;if(typeof applyReadingResumePosition==='function')applyReadingResumePosition(content);if(pdf&&readingPane.pdf&&Array.isArray(window.SINQ_LECTURE_PAGES)&&!readingPane.scroll)jumpReadingPage(readingPane.page);
  }catch(e){if(serial===readingPane.serial)content.innerHTML=`<section class="readerEmpty readerEmptyState" role="alert"><h3>课件暂时没有打开</h3><p>${esc(e.message||'连接暂时中断，请稍后重试。')}</p><div class="readerEmptyActions"><button class="secondary" onclick="loadReadingPane()">重试读取课件</button><button class="newChat" onclick="switchReadingMobile('notebook')">先记笔记</button></div></section>`}
}
function quoteReadingSelection(){
 const selection=window.getSelection(),area=document.getElementById('readingScroll'),status=document.getElementById('readingStatus');
 if(!selection?.anchorNode||!area?.contains(selection.anchorNode)||!selection.toString().trim()){if(status)status.textContent='先在课件提取文字中选中一段。PDF 请先切换到提取文字。';return}
 const text=selection.toString().trim().slice(0,1500);learningDraft='请结合当前课程，帮我理解这段内容：\n“'+text+'”';saveLearningDraft();const prompt=document.getElementById('materialPrompt');prompt.value=learningDraft;if(readingPane.open)toggleNotebookAI(true);prompt.focus();if(status)status.textContent='已放入问题，确认后再发送。';
}

function fitNotebookViewport(){if(typeof scheduleMobileNotebook==='function')scheduleMobileNotebook();const root=document.querySelector('.studySplit.splitOpen');if(root){root.style.setProperty('--notebook-top',Math.max(0,root.getBoundingClientRect().top)+'px');const area=document.getElementById('readingScroll');if(area?.clientHeight&&!readingPane.scroll)jumpReadingPage(readingPane.page)}}
if(typeof window!=='undefined')window.addEventListener?.('resize',fitNotebookViewport);

function rememberNotebookMode(){try{sessionStorage.setItem('courselex-notebook-mode:'+session.user.id+':'+workspaceScope(),readingPane.open?'1':'0');sessionStorage.setItem('courselex-notebook-week:'+session.user.id+':'+workspaceScope(),String(readingPane.week||''))}catch{}}

function trackReadingScroll(){const area=document.getElementById('readingScroll');if(!area||!area.clientHeight||!area.getBoundingClientRect().width)return;readingPane.scroll=area.scrollTop;const top=area.getBoundingClientRect().top,figures=[...area.querySelectorAll('.readerSlides figure')],current=figures.filter(f=>f.getBoundingClientRect().top<=top+20).at(-1);if(!current){if(typeof saveReadingResume==='function')saveReadingResume();return}readingPane.page=Number(current.id.replace('lecturePage',''));const label=document.querySelector('#readingPageMenu summary strong');if(label)label.textContent='第 '+readingPane.page+' 页';if(typeof saveReadingResume==='function')saveReadingResume()}

function renderNotebookMobileViews(){return '<div class="notebookMobileViews" role="group" aria-label="手机阅读布局">'+[['reader','课件'],['stacked','上下分屏'],['notebook','笔记']].map(([view,label])=>'<button data-mobile-view="'+view+'" aria-pressed="'+(readingPane.mobile===view)+'" onclick="switchReadingMobile(\''+view+'\')">'+label+'</button>').join('')+'</div>'}

async function navigateLearningHome(){
 const uid=session?.user.id;
 if(typeof flushWorkspace==='function'&&!await flushWorkspace())return false;
 if(uid!==session?.user.id)return false;
 if(document.getElementById('courseDialog')&&typeof closeCourseDialog==='function'&&!await closeCourseDialog())return false;
 readingPane.open=false;readingPane.aiOpen=false;rememberNotebookMode();learningGuide=null;
 if(assistantBusy)renderStudyAssistant();else clearLearningConversation();
 window.scrollTo?.({top:0,behavior:'instant'});return true;
}
